modulo(A, B, Remainder) :- Remainder is A mod B.

solve :-
    Exponent is 859,
    modulo(Exponent, 6, Remainder),
    (Remainder =:= 1 -> Digits = [4, 2, 8] ;
     Remainder =:= 2 -> Digits = [2, 8, 5] ;
     Remainder =:= 3 -> Digits = [8, 5, 7] ;
     Remainder =:= 4 -> Digits = [5, 7, 1] ;
     Remainder =:= 5 -> Digits = [7, 1, 4] ;
     Digits = [1, 4, 2]),
    format('~d~d~d', Digits).

