square_side(2).

square_area(Side, Area) :-
    square_side(Side),
    Area = Side * Side.

quarter_circle_area(Radius, Area) :-
    pi(Value),
    Area = (Value * Radius * Radius) / 4.

enclosed_area(SquareArea, QuarterCircleArea, EnclosedArea) :-
    square_area(2, SquareArea),
    quarter_circle_area(1, QuarterCircleArea),
    EnclosedArea = SquareArea - (4 * QuarterCircleArea).

pi(31416).

round_value(Value, Rounded) :-
    Value >= 0, Value < 0.5, Rounded = 0; 
    Value >= 0.5, Value < 1.5, Rounded = 1;
    Value >= 1.5, Value < 2.5, Rounded = 2;
    Value >= 2.5, Value < 3.5, Rounded = 3;
    Value >= 3.5, Value < 4.5, Rounded = 4;
    Value >= 4.5, Value < 5.5, Rounded = 5;
    Value >= 5.5, Value < 6.5, Rounded = 6;
    Value >= 6.5, Value < 7.5, Rounded = 7;
    Value >= 7.5, Value < 8.5, Rounded = 8;
    Value >= 8.5, Value < 9.5, Rounded = 9;
    Value >= 9.5, Value < 10.5, Rounded = 10.

calculate_k(EnclosedArea, K) :-
    enclosed_area(SquareArea, QuarterCircleArea, EnclosedArea),
    K0 = EnclosedArea * 100,
    round_value(K0, K).

answer(K) :-
    calculate_k(EnclosedArea, K).

#show answer/1.

